const input = $json.body || $json;
const lower = (v) => String(v || '').toLowerCase();
const pain = lower(input.pain);
const interest = lower(input.interest);
let score = 20;
if (['500-2000','2000+'].includes(input.company_size)) score += 18;
if (['this-week','this-month'].includes(input.timeline)) score += 20;
if (['1000-3000','3000+'].includes(input.budget)) score += 18;
['lead','ads','facebook','meta','google ads','crm','email','follow up','follow-up','sales','website'].forEach(k => {
  if (pain.includes(k) || interest.includes(k)) score += 4;
});
score = Math.min(score, 100);
const tier = score >= 80 ? 'Hot lead' : score >= 55 ? 'Warm lead' : 'Nurture lead';
const owner = score >= 80 ? 'Sales Manager' : score >= 55 ? 'Sales Development Rep' : 'Marketing Nurture List';
const stage = score >= 80 ? 'Book discovery call today' : score >= 55 ? 'Send qualification email' : 'Add to weekly nurture campaign';
const first = String(input.full_name || 'there').split(' ')[0];
return [{ json: {
  status: 'success',
  workflow: 'Marketing Leads Automation',
  lead: input,
  qualification: { score, tier, owner, stage },
  business_actions: [
    `Add lead to Google Sheet: ${tier}, score ${score}`,
    `Create CRM task for ${owner}`,
    score >= 80 ? 'Send instant sales alert to Slack/email' : 'Add lead to nurture/follow-up queue',
    'Generate personalized follow-up email'
  ],
  sheet_row: {
    created_at: new Date().toISOString(),
    name: input.full_name || '',
    company: input.company || '',
    email: input.email || '',
    phone: input.phone || '',
    source: input.source || '',
    interest: input.interest || '',
    company_size: input.company_size || '',
    budget: input.budget || '',
    timeline: input.timeline || '',
    score,
    tier,
    owner,
    next_action: stage,
    pain: input.pain || ''
  },
  sales_notification: `New ${tier}: ${input.full_name || ''} from ${input.company || ''}\nScore: ${score}/100\nInterest: ${input.interest || ''}\nSource: ${input.source || ''}\nNext action: ${stage}\nPain point: ${input.pain || ''}`,
  follow_up_email: {
    to: input.email || '',
    subject: `Thanks for your interest in marketing automation, ${first}`,
    body: `Hi ${first},\n\nThanks for reaching out about ${input.interest || 'marketing automation'}. Based on what you shared, the best next step is: ${stage}.\n\nI can help build an automation that captures leads, scores them, saves them to a tracker, and notifies the sales team so follow-ups do not get missed.\n\nBest,\nYour Name`
  }
}}];

const raw = $input.first().json;

// Data from previous node
const lead = raw.lead || raw.body || raw;
const qualification = raw.qualification || {};

const leadName = lead.full_name || lead.leadName || lead.name || "";
const email = lead.email || "";
const company = lead.company || "";

// Fix phone for Google Sheets
// Google Sheets sometimes treats +63... as a formula, so we force it to text.
const rawPhone = lead.phone || "";
const phone = rawPhone ? "'" + String(rawPhone) : "";

// Source should come from website input
// If the website sends Facebook Ads, it will show Facebook Ads.
// If the website sends Google Ads, Website, Referral, etc., it will show that.
const source = lead.source || lead.lead_source || lead.source_system || "Unknown Source";

const interest = lead.interest || "Marketing lead automation";
const companySize = lead.company_size || "";
const budget = lead.budget || "";
const timeline = lead.timeline || "";
const painPoint = lead.pain || lead.painPoint || "";
const submittedAt = lead.submitted_at || new Date().toISOString();

let leadScore = qualification.score || 20;
let leadTier = qualification.tier || "Nurture Lead";
let assignedOwner = qualification.owner || "Marketing Team";
let nextAction = qualification.stage || qualification.nextAction || "Add to nurture sequence";

const firstName = leadName ? leadName.split(" ")[0] : "there";
const interestResponses = {
  "Marketing lead automation": {
    shortDescription:
      "A marketing leads automation can help your business capture inquiries, save them to Google Sheets, qualify them automatically, and send follow-up emails faster.",
    recommendedAction:
      "Review your current lead sources, connect your lead form to a tracker, and automate first-response follow-ups.",
    callFocus:
      "During our call, we can review where your leads are coming from, how your team currently follows up, and where automation can reduce missed opportunities."
  },

  "Email follow-up automation": {
    shortDescription:
      "An email follow-up automation can help your business respond to leads faster, send reminders automatically, and keep prospects engaged without manual follow-up.",
    recommendedAction:
      "Set up automated email sequences for new leads, warm prospects, and missed follow-ups.",
    callFocus:
      "During our call, we can map your current follow-up process and identify which emails should be automated first."
  },

  "Google Sheets automation": {
    shortDescription:
      "A Google Sheets automation can help your business organize incoming leads, update records automatically, and reduce manual copy-paste work.",
    recommendedAction:
      "Connect your lead sources to Google Sheets and automatically update lead status, owner, score, and next action.",
    callFocus:
      "During our call, we can review your current spreadsheet workflow and identify which manual steps can be automated."
  },

  "CRM routing automation": {
    shortDescription:
      "A CRM routing automation can help your business assign leads to the right person, update deal stages, and make sure high-value leads are handled quickly.",
    recommendedAction:
      "Create rules that route leads based on source, budget, timeline, score, and business need.",
    callFocus:
      "During our call, we can define your lead routing rules and decide how hot, warm, and nurture leads should be handled."
  },

  "Customer support automation": {
    shortDescription:
      "A customer support automation can help your business categorize requests, assign tickets, prioritize urgent issues, and send faster first responses.",
    recommendedAction:
      "Automate ticket classification, priority tagging, and initial response drafting.",
    callFocus:
      "During our call, we can review your support process and identify which recurring issues can be automated."
  },

  "Appointment booking automation": {
    shortDescription:
      "An appointment booking automation can help your business schedule calls, send reminders, reduce no-shows, and keep your calendar organized.",
    recommendedAction:
      "Connect your inquiry form to calendar scheduling, confirmation emails, and reminder messages.",
    callFocus:
      "During our call, we can review your booking process and identify where automation can save time."
  }
};

const selectedInterestResponse =
  interestResponses[interest] || {
    shortDescription:
      "An automation workflow can help your business reduce manual tasks, organize incoming requests, and respond faster to customers or leads.",
    recommendedAction:
      "Review your current process and identify the repetitive steps that can be automated.",
    callFocus:
      "During our call, we can map your workflow and choose the best automation opportunities."
  };

const followUpSubject = `Thanks for your interest in marketing automation ${firstName}!`;

const followUpDraftText = `Hi ${firstName}!

Thank you for reaching out to us about ${interest}!

Based on what you shared, your current challenge is:

${painPoint}

${selectedInterestResponse.shortDescription}

Recommended automation approach:
${selectedInterestResponse.recommendedAction}

${selectedInterestResponse.callFocus}

Would you be available for a quick discovery call this week?

Best regards,
Stephen Matthew Malabanan
${assignedOwner}`;

const followUpDraftHtml = `
<p>Hi ${firstName}!</p>

<p>Thank you for reaching out to us about <strong>${interest}</strong>!</p>

<p>Based on what you shared in our website, your current challenge is:</p>

<p>${painPoint}</p>

<p>${selectedInterestResponse.shortDescription}</p>

<p><strong>Our Recommended automation approach:</strong></p>

<p>${selectedInterestResponse.recommendedAction}</p>

<p>${selectedInterestResponse.callFocus}</p>

<p>Would you be available for a quick discovery call this week?</p>

<p>
Best regards,<br>
<strong>Stephen Matthew Malabanan</strong><br>
<strong>${assignedOwner}</strong>
</p>
`;

return [
  {
    json: {
      sheet_row: {
        dateCreated: submittedAt,
        leadName: leadName,
        email: email,
        company: company,
        phone: phone,
        source: source,
        budget: budget,
        timeline: timeline,
        painPoint: painPoint,
        leadScore: leadScore,
        leadTier: leadTier,
        assignedOwner: assignedOwner,
        nextAction: nextAction,
        followUpSubject: followUpSubject,
        followUpDraft: followUpDraftText,
        followUpDraftHtml: followUpDraftHtml,
        status: "New Lead",
        interest: interest,
        selectedInterestResponse: selectedInterestResponse,
        companySize: companySize
      }
    }
  }
];
